// Package eff is the effect runtime that code generated by the Alder
// compiler imports: Query and Task values are plain data (trees of steps)
// built with the constructors below, and Run interprets them eagerly
// against an Env.
//
// Generated code only builds trees and hands them to Run or RunQuery; it
// never inspects a tree. A tree may be run any number of times: running it
// does not change it.
package eff

import (
	"context"
	"errors"
	"fmt"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

// Kind records which effect the checker proved a tree to be. Query and Task
// share one representation; Kind decides how Run treats it.
type Kind int

const (
	// KQuery runs with no transaction; a write Call is an internal error.
	KQuery Kind = iota
	// KTask runs inside at most one transaction, begun when first needed.
	KTask
)

// Step is implemented only by Query and Task (it is sealed). Generated code
// never implements it; it may use it to name "any effect value".
type Step[T any] interface{ step() }

// Query is a read-only effect producing a T. Build one with Q; run it with
// RunQuery. The zero Query is not valid.
type Query[T any] struct{ node node }

// Task is an effect producing a T that may write. Build one with the
// constructors below; run it with Run. The zero Task is not valid.
type Task[T any] struct{ node node }

func (Query[T]) step() {}
func (Task[T]) step()  {}

// node is the untyped tree: one of pure, bind, call, fail, notFound.
type node interface{ isNode() }

type pure struct{ v any }

type bind struct {
	e node
	f func(any) node
}

type call struct {
	name  string
	write bool
	fn    func(*Env) (any, error)
}

type fail struct{ msg string }

type notFound struct{}

func (pure) isNode()     {}
func (bind) isNode()     {}
func (call) isNode()     {}
func (fail) isNode()     {}
func (notFound) isNode() {}

// as unwraps a value carried through the untyped tree. A nil interface
// comes back as T's zero value, so Pure[error](nil) and the like work.
func as[T any](v any) T {
	if v == nil {
		var zero T
		return zero
	}
	return v.(T)
}

// Pure is an effect that performs nothing and produces v. It is a Task;
// where a Query is expected, emit Q(Pure(v)).
func Pure[T any](v T) Task[T] { return Task[T]{pure{v}} }

// Q reinterprets a tree as a Query. It costs nothing and changes nothing
// about the tree; generated code uses it for Query positions. Whether the
// tree is safe to run as a Query is the checker's business; Run enforces
// only that no write Call is reached.
func Q[T any](t Task[T]) Query[T] { return Query[T]{t.node} }

// T is the inverse of Q: it reinterprets a Query as a Task, so the emitter
// can use Bind, Map and All (which take Tasks) inside a Query and then wrap
// the result with Q again. T(Q(t)) is t.
func T[A any](q Query[A]) Task[A] { return Task[A]{q.node} }

// Bind runs e, then the effect f builds from its result. If e fails
// (Fail, NotFound or an error) f is not called. Bind chains of any depth
// and nesting are safe: Run does not use the Go stack to follow them.
func Bind[A, B any](e Task[A], f func(A) Task[B]) Task[B] {
	return Task[B]{bind{e.node, func(v any) node { return f(as[A](v)).node }}}
}

// Map runs e and applies the pure function f to its result.
func Map[A, B any](f func(A) B, e Task[A]) Task[B] {
	return Task[B]{bind{e.node, func(v any) node { return pure{f(as[A](v))} }}}
}

// All runs es in order and produces their results in the same order. It
// stops at the first failure; later effects are not run. All of no effects
// produces an empty (non-nil) slice. The slice es is copied, so the caller
// may reuse it.
func All[A any](es []Task[A]) Task[[]A] {
	es = append([]Task[A]{}, es...)
	var from func(i int, out []A) node
	from = func(i int, out []A) node {
		if i == len(es) {
			return pure{out}
		}
		return bind{es[i].node, func(v any) node { return from(i+1, append(out, as[A](v))) }}
	}
	// The result slice is made when the effect runs, not when it is built,
	// so running the same tree twice never shares a slice.
	return Task[[]A]{bind{pure{nil}, func(any) node { return from(0, make([]A, 0, len(es))) }}}
}

// Fail is an effect that fails with msg (Task.fail, a @unique violation, a
// capability failure). Run returns it as *ErrFail and, in a Task, rolls the
// transaction back.
func Fail[T any](msg string) Task[T] { return Task[T]{fail{msg}} }

// NotFound is an effect that fails with ErrNotFound (a missing record).
// Run rolls a Task's transaction back.
func NotFound[T any]() Task[T] { return Task[T]{notFound{}} }

// Call is one effect step. name is for the log and Env.Trace ("Db.get
// Todo", "Password.verify"); write says whether it may write (a write Call
// reached while running a Query is an internal error); fn runs with the Env
// — whose Ctx carries the Env (EnvFrom) and whose Transaction begins the
// Task's transaction on first use — and returns the value or an error. fn may return *ErrFail or ErrNotFound to fail the way Fail and
// NotFound do; any other error is passed through unchanged. fn may replace
// Env.Session. fn must not keep the Env after it returns.
func Call[T any](name string, write bool, fn func(*Env) (T, error)) Task[T] {
	return Task[T]{call{name, write, func(e *Env) (any, error) {
		v, err := fn(e)
		if err != nil {
			return nil, err
		}
		return v, nil
	}}}
}

// Env is what effects run against. Run reads Ctx, Store and Log, makes Ctx
// carry the Env and Kind record its kind while it runs, restores Tx, Ctx and
// Kind when it returns, and
// appends to Trace; Transaction sets Tx when a Task's transaction is begun;
// everything else is for Call functions.
type Env struct {
	Ctx     context.Context // checked before each Call; nil means never cancelled; carries the Env while Run runs
	Store   Store           // nil: Tasks run with no transaction (Tx stays nil)
	Tx      Tx              // the running Task's transaction once begun (Transaction); nil in a Query
	Session any             // the app's session value; SessionPut replaces it
	// SessionPut is set by Session.put (and restored with Session when its Task fails): the
	// router then stores the session cookie, issued anew, even when the value is unchanged —
	// logging in again as the same user starts a new 30-day lifetime.
	SessionPut bool
	Caps       map[string]any          // "Auth.Login.Password" → implementation
	Now        func() time.Time        // the clock
	Log        func(level, msg string) // level is "info", "warn" or "effect"; nil: no log
	Trace      []string                // every Call name in order (dev log / tests)
	Kind       Kind                    // the kind of the effect Run is running (set by Run, restored when it returns)
	Rec        *Recorder               // dev mode: per-request trace with timings (nil: none, no cost)
	Within     *Within                 // nil: a Task begins its own transaction on Store; else it runs inside Within.Tx (Run)

	beginTx func() (Tx, error) // set by Run for a Task with a Store: begins Tx
	active  bool               // Run is running (RunInner may run inside it); restored when it returns
}

// Transaction is the running Task's transaction, begun on first use: the
// first call inside a Task run against a Store begins it and records it in
// e.Tx; later calls return the same one. In a Query, with no Store, or
// outside Run it is e.Tx (nil in a Query). A Begin error is returned and
// nothing is recorded.
func (e *Env) Transaction() (Tx, error) {
	if e.Tx != nil || e.beginTx == nil {
		return e.Tx, nil
	}
	tx, err := e.beginTx()
	if err != nil {
		return nil, err
	}
	e.Tx = tx
	return tx, nil
}

// Within is an outer transaction an effect runs inside instead of beginning its own: an Alder
// test's browser hands the router one, so every request of the test runs in the test's
// transaction (the test's rows are visible to the page, no second connection is opened). Run
// brackets a Task with a savepoint on Tx (when Savepoints is set), released when the Task
// succeeds and rolled back to when it fails, so a failed request undoes only its own writes;
// nothing is committed. A Query reads through Tx.
type Within struct {
	Tx         Tx
	Savepoints Savepointer // nil: no savepoint, and a failure undoes nothing
}

// Savepointer is a Store whose transactions support savepoints (db.SQLite; db.Savepointer is
// this interface).
//
// A savepoint is a named mark inside an open transaction. Savepoint sets the mark; RollbackTo
// undoes every write made since the mark (the writes made before it, earlier in the same
// transaction, stay) and keeps the mark; Release forgets the mark and keeps its writes as part
// of the enclosing transaction (or the enclosing savepoint), so they are committed or rolled
// back with it. Savepoints nest: one opened while another is open belongs to it, and rolling
// back the outer one undoes the inner one too.
type Savepointer interface {
	Savepoint(ctx context.Context, tx Tx, name string) error
	Release(ctx context.Context, tx Tx, name string) error
	RollbackTo(ctx context.Context, tx Tx, name string) error
}

// savepoints numbers the savepoints SavepointName gives, so nested and sequential ones never
// share a name.
var savepoints atomic.Int64

// SavepointName is a fresh savepoint name (alder_t1, alder_t2, …): Run's under a Within and
// rtesting.Inner's draw from the same counter.
func SavepointName() string { return "alder_t" + strconv.FormatInt(savepoints.Add(1), 10) }

type envKey struct{}

// EnvFrom is the Env of the effect running with ctx, or nil. Run puts its
// Env in env.Ctx, which generated code passes to every store operation and
// capability method, so a capability implementation can reach the running
// Task (db.TxFrom(ctx) is its transaction).
func EnvFrom(ctx context.Context) *Env {
	if ctx == nil {
		return nil
	}
	e, _ := ctx.Value(envKey{}).(*Env)
	return e
}

// Store begins transactions. It is independent of any particular database.
type Store interface {
	Begin(ctx context.Context) (Tx, error)
}

// Tx is one transaction.
type Tx interface {
	Commit() error
	Rollback() error
}

// ErrFail is the error of an effect that failed with a message: Task.fail,
// a @unique violation or a capability failure.
type ErrFail struct{ Msg string }

func (e *ErrFail) Error() string { return e.Msg }

// ErrNotFound is the error of an effect that looked for a record that is
// not there. Run returns this exact value, so err == ErrNotFound works.
var ErrNotFound = errors.New("not found")

// ErrCapability is the error of a capability whose implementation (an adapter) returned an
// error: Name is the step ("Password.verify") and Err the adapter's error. Generated
// capability Calls wrap with CapError. A route answers it as it answers any other error (500);
// Test.run (rtesting.Inner) turns it into `Err "<Name>: <msg>"`, so a capability's error is a
// failure a test can observe.
type ErrCapability struct {
	Name string
	Err  error
}

func (e *ErrCapability) Error() string { return e.Name + ": " + e.Err.Error() }

// Unwrap is the adapter's error, so errors.Is and errors.As see through the wrapping.
func (e *ErrCapability) Unwrap() error { return e.Err }

// CapError is what a generated capability Call returns for its adapter's error err: nil for
// nil; err itself when it is already a failure (*ErrFail, ErrNotFound) or an ErrCapability;
// otherwise &ErrCapability{name, err}.
func CapError(name string, err error) error {
	var f *ErrFail
	var c *ErrCapability
	if err == nil || errors.Is(err, ErrNotFound) || errors.As(err, &f) || errors.As(err, &c) {
		return err
	}
	return &ErrCapability{Name: name, Err: err}
}

// Note records name as a step of the Call running now, taken before it: it is logged at level
// "effect" and put in Trace just before the Call's own name (appended when Trace is empty). A
// store operation uses it for a part of its work the trace names apart: db.All on a Db.mine
// select notes `Db.mine Todo`, so the trace reads ["Db.mine Todo", "Db.all Todo"].
func (e *Env) Note(name string) {
	if e.Log != nil {
		e.Log("effect", name)
	}
	if n := len(e.Trace); n > 0 {
		t := make([]string, 0, n+1) // a new array: a slice of the old one held elsewhere keeps its names
		e.Trace = append(append(append(t, e.Trace[:n-1]...), name), e.Trace[n-1])
		return
	}
	e.Trace = append(e.Trace, name)
}

// Recorder is the dev-mode per-request trace: every Call with its duration and, for a capability,
// whether an adapter or a fake answered; every SQL statement the store ran. A nil Env.Rec records
// nothing. It is filled by Run and by rt/db; the dev panel renders it.
type Recorder struct {
	mu    sync.Mutex
	Steps []StepRec
	SQL   []SQLRec
}

// StepRec is one recorded Call: Name, how long it took, and Cap ("adapter", "fake" or "") for a
// capability call.
type StepRec struct {
	Name string
	Ms   float64
	Cap  string
}

// SQLRec is one statement with its arguments, duration and the rows it touched (-1: not counted).
type SQLRec struct {
	Stmt string
	Args []any
	Ms   float64
	Rows int64
	// Step is the index of the effect step that ran the statement (the steps recorded before
	// it), set by AddSQL: statements of one step ran from one bulk operation.
	Step int
}

// AddStep records a step.
func (r *Recorder) AddStep(s StepRec) { r.mu.Lock(); r.Steps = append(r.Steps, s); r.mu.Unlock() }

// AddSQL records a statement.
func (r *Recorder) AddSQL(s SQLRec) {
	r.mu.Lock()
	s.Step = len(r.Steps) // a step is recorded when it finishes, so the running one has this index
	r.SQL = append(r.SQL, s)
	r.mu.Unlock()
}

// SetRows records n as the rows read by the last statement stmt whose rows were not counted yet
// (a read's rows are known only once its caller has read them).
func (r *Recorder) SetRows(stmt string, n int64) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for i := len(r.SQL) - 1; i >= 0; i-- {
		if r.SQL[i].Stmt == stmt && r.SQL[i].Rows < 0 {
			r.SQL[i].Rows = n
			return
		}
	}
}

// Ms is a duration in milliseconds.
func Ms(d time.Duration) float64 { return float64(d.Microseconds()) / 1000 }

// CapKind is "adapter" or "fake" for a capability step named "Cap.op" (the implementation's type
// name decides: the generated fakes are named Fake…), "" for any other step.
func CapKind(env *Env, name string) string {
	c, _, ok := strings.Cut(name, ".")
	if !ok {
		return ""
	}
	for k, impl := range env.Caps {
		if k == c || strings.HasSuffix(k, "."+c) {
			if strings.Contains(strings.ToLower(fmt.Sprintf("%T", impl)), "fake") {
				return "fake"
			}
			return "adapter"
		}
	}
	return ""
}
